// Throwaway UI test: right-click menus, palette drag & drop, drag-to-connect against a live backend.
import assert from "node:assert/strict";
import puppeteer from "puppeteer-core";

const API = "http://localhost:8000";
const SHOTS = process.argv[2];
const post = async (path, body) => {
  const r = await fetch(API + path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  if (!r.ok) throw new Error(`${path}: ${await r.text()}`);
  return r.json();
};
const get = async (path) => (await fetch(API + path)).json();
const inputsOf = async (id) => (await get(`/nodes/${id}/inputs`)).map((n) => n.id).sort();

// seed: SRC-001 -> EVD-001 -> CLM-001, plus EVD-002
await post("/import/csv", { filename: "f.csv", text: "ref,text\nr1,seats too narrow\nr2,cabin noisy\n", created_by: "PM:test" });
await post("/tools/query_data", { content: { text: "seats too narrow" }, source_ids: ["SRC-001"], created_by: "agent:loop" });
await post("/tools/query_data", { content: { text: "cabin noisy" }, source_ids: ["SRC-001"], created_by: "agent:loop" });
await post("/tools/add_claim", { content: { text: "seats too narrow" }, evidence_ids: ["EVD-001"], created_by: "agent:loop" });

const browser = await puppeteer.launch({
  executablePath: "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",
  headless: true, defaultViewport: { width: 1500, height: 900 },
});
const page = await browser.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
await page.goto(`${API}/ui/`);
await page.waitForFunction(() => window.cy && window.cy.nodes().length === 4);
await page.type("#pm", "alex");
await page.$eval("#pm", (el) => el.dispatchEvent(new Event("change")));

const graphBox = await (await page.$("#graph")).boundingBox();
const nodePos = (id) => page.evaluate((id) => window.cy.getElementById(id).renderedPosition(), id)
  .then((p) => ({ x: graphBox.x + p.x, y: graphBox.y + p.y }));
const clickMenu = async (label) => {
  await page.waitForSelector("#menu:not([hidden])");
  const items = await page.$$("#menu button");
  for (const b of items) if ((await b.evaluate((e) => e.textContent)).startsWith(label)) return b.click();
  throw new Error(`no menu item ${label}`);
};
const fillAndCreate = async (text) => {
  await page.waitForSelector("#draftText");
  await page.type("#draftText", text);
  await page.click("#createNode");
};
const waitNode = (id) => page.waitForFunction((id) => window.cy.getElementById(id).nonempty(), {}, id);

// 1. right-click empty canvas -> New Note
await page.mouse.click(graphBox.x + 60, graphBox.y + graphBox.height - 60, { button: "right" });
await page.screenshot({ path: `${SHOTS}/ui_menu_bg.png` });
await clickMenu("New Note");
await fillAndCreate("Workshop: customers in DE care about cabin noise");
await waitNode("NTE-001");
assert.deepEqual(await inputsOf("NTE-001"), []);
console.log("1 ok: right-click background -> Note");

// 2. right-click a node -> New Claim from EVD-002
let p = await nodePos("EVD-002");
await page.mouse.click(p.x, p.y, { button: "right" });
await page.screenshot({ path: `${SHOTS}/ui_menu_node.png` });
await clickMenu("New Claim from EVD-002");
await fillAndCreate("Motorway cabin noise bothers owners");
await waitNode("CLM-002");
assert.deepEqual(await inputsOf("CLM-002"), ["EVD-002"]);
console.log("2 ok: right-click node -> Claim built on it");

// 3. counter-evidence via menu -> contradicts relation
p = await nodePos("CLM-001");
await page.mouse.click(p.x, p.y, { button: "right" });
await clickMenu("Counter-evidence");
await fillAndCreate("Seat width rated 4.5/5 in the customer study");
await waitNode("EVD-003");
const edges = await get("/edges");
assert.equal(edges.find((e) => e.from_id === "EVD-003").relation, "contradicts");
console.log("3 ok: counter-evidence -> contradicts edge");

// 4. palette drag & drop onto a node -> Question with that node as input
p = await nodePos("CLM-002");
await page.evaluate(({ x, y }) => {
  const dt = new DataTransfer();
  document.querySelector('[data-new="Question"]').dispatchEvent(new DragEvent("dragstart", { dataTransfer: dt, bubbles: true }));
  const target = document.elementFromPoint(x, y);
  target.dispatchEvent(new DragEvent("dragover", { dataTransfer: dt, bubbles: true, cancelable: true, clientX: x, clientY: y }));
  target.dispatchEvent(new DragEvent("drop", { dataTransfer: dt, bubbles: true, cancelable: true, clientX: x, clientY: y }));
}, p);
await page.waitForSelector("#draftText");
await page.screenshot({ path: `${SHOTS}/ui_drop_form.png` });
// add a second input by clicking a node in the graph while the form is open
p = await nodePos("NTE-001");
await page.mouse.click(p.x, p.y);
await fillAndCreate("Is motorway noise a DE-only issue?");
await waitNode("QST-001");
assert.deepEqual(await inputsOf("QST-001"), ["CLM-002", "NTE-001"]);
console.log("4 ok: palette drop onto node + click-to-pick second input");

// 5. drag EVD-002 onto CLM-001 -> connect (EVD-002 becomes input of CLM-001 v2)
const from = await nodePos("EVD-002");
const to = await nodePos("CLM-001");
await page.mouse.move(from.x, from.y);
await page.mouse.down();
await page.mouse.move((from.x + to.x) / 2, (from.y + to.y) / 2, { steps: 5 });
await page.mouse.move(to.x, to.y, { steps: 5 });
await page.mouse.up();
await page.waitForSelector("#doLink");
await page.screenshot({ path: `${SHOTS}/ui_connect_form.png` });
await page.type("#reason", "noise evidence also supports the seat claim");
await page.click("#doLink");
await waitNode("CLM-003");
assert.deepEqual(await inputsOf("CLM-003"), ["EVD-001", "EVD-002"]);
assert.equal((await get("/nodes/CLM-001")).status, "stale");
console.log("5 ok: drag node onto node -> new version with extra input, old one stale");

// 6. a loop is refused with a readable message
p = await nodePos("EVD-001");
await page.mouse.click(p.x, p.y, { button: "right" });
await clickMenu("Connect: add an input to EVD-001");
p = await nodePos("CLM-003");
await page.mouse.click(p.x, p.y);
await page.type("#reason", "should fail");
await page.click("#doLink");
await page.waitForFunction(() => document.querySelector("#toast").textContent.includes("loop"));
console.log("6 ok: loop refused:", await page.$eval("#toast", (e) => e.textContent));

await page.keyboard.press("Escape");
await page.screenshot({ path: `${SHOTS}/ui_final.png` });
assert.deepEqual(errors, [], "no page errors");
await browser.close();
console.log("all UI checks passed");

