// Throwaway E2E: PM requests via the GUI, real Run-agent click, LLM handles them first.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import puppeteer from "puppeteer-core";

const API = "http://localhost:8000";
const SHOTS = process.argv[2];
const CSV = "C:/Users/Alex/HAckAI/kolosok-rehack/agent-loop/sample_data/demo_feedback.csv";
const post = async (path, body) => {
  const r = await fetch(API + path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  if (!r.ok) throw new Error(`${path}: ${await r.text()}`);
  return r.json();
};
const get = async (path) => (await fetch(API + path)).json();
const waitRun = async () => { while ((await get("/agent/status")).running) await new Promise((r) => setTimeout(r, 1000)); };
const print = (n) => console.log(`  ${n.id} ${n.created_by} [${(n.inputs || []).join(",")}] ${JSON.stringify(n.content).slice(0, 140)}`);
const dump = async (since) => {
  const nodes = await get("/nodes");
  for (const n of nodes.slice(since)) print({ ...n, inputs: (await get(`/nodes/${n.id}/inputs`)).map((i) => i.id) });
  return nodes.length;
};

await post("/import/csv", { filename: "demo_feedback.csv", text: readFileSync(CSV, "utf8"), created_by: "PM:alex" });
await post("/agent/run", { max_actions: 4 });
await waitRun();
console.log("baseline run:");
let seen = await dump(0);

const browser = await puppeteer.launch({
  executablePath: "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",
  headless: true, defaultViewport: { width: 1500, height: 900 },
});
const page = await browser.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
await page.goto(`${API}/ui/`);
await page.waitForFunction((n) => window.cy && window.cy.nodes().length === n, {}, seen);
await page.type("#pm", "alex");
await page.$eval("#pm", (el) => el.dispatchEvent(new Event("change")));
const box = await (await page.$("#graph")).boundingBox();
const rightClick = async (id) => {
  const p = await page.evaluate((id) => window.cy.getElementById(id).renderedPosition(), id);
  await page.mouse.click(box.x + p.x, box.y + p.y, { button: "right" });
};
const clickMenu = async (label) => {
  await page.waitForSelector("#menu:not([hidden])");
  for (const b of await page.$$("#menu button")) if ((await b.evaluate((e) => e.textContent)).startsWith(label)) return b.click();
  throw new Error(`no menu item ${label}`);
};

// PM asks the agent to challenge CLM-001 and to dig deeper on EVD-001
await rightClick("CLM-001");
await clickMenu("Ask the agent to challenge");
await page.waitForSelector("#createNode");
await page.click("#createNode");
await page.waitForFunction(() => window.cy.getElementById("QST-001").nonempty());
await rightClick("EVD-001");
await clickMenu("Ask the agent to dig deeper");
await page.waitForSelector("#createNode");
await page.click("#createNode");
await page.waitForFunction(() => window.cy.getElementById("QST-002").nonempty());
const stats = await page.$eval("#stats", (e) => e.textContent);
assert.match(stats, /2 waiting for the agent/);
await page.screenshot({ path: `${SHOTS}/steer_requests.png` });
console.log("requests created via GUI; stats:", stats);

// real Run agent click, 3 actions
await page.$eval("#actions", (e) => { e.value = "3"; });
await page.click("#run");
await page.waitForFunction(() => document.querySelector("#agentStatus").textContent.includes("running"));
await waitRun();
await page.waitForFunction(() => document.querySelector("#agentStatus").textContent.includes("finished"), { timeout: 10000 });
console.log("agent run after requests:");
await dump(seen);
const statsAfter = await page.$eval("#stats", (e) => e.textContent);
console.log("stats after:", statsAfter);
await page.evaluate(() => { location.hash = "#QST-001"; location.reload(); });
await page.waitForSelector("#detail h2");
await page.screenshot({ path: `${SHOTS}/steer_after.png` });
console.log("agent log:\n" + (await get("/agent/status")).log);
assert.deepEqual(errors, [], "no page errors");
await browser.close();

