// Throwaway E2E for phase 4: real counter-evidence via challenge, Answer button, audit timeline.
import assert from "node:assert/strict";
import puppeteer from "puppeteer-core";

const API = "http://localhost:8000";
const SHOTS = process.argv[2];
const post = async (path, body) => {
  const r = await fetch(API + path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  if (!r.ok) throw new Error(`${path}: ${await r.text()}`);
  return r.json();
};
const get = async (path) => (await fetch(API + path)).json();

// data where one row really contradicts the claim
const csv = `source_ref,market,text
Owner survey 101,Germany,The front seats are too narrow for tall drivers.
Owner survey 102,Germany,"The front seats are wide and comfortable, even for tall drivers like me."
Owner survey 103,Germany,Road noise on the motorway is too loud.
`;
