  const ins = edges.filter((e) => e.from_id === n.id).map((e) => `${e.to_id}${e.relation === "derived_from" ? "" : `(${e.relation})`}`);
  console.log(`  ${n.id} ${n.created_by} [${ins.join(",")}] ${JSON.stringify(n.content).slice(0, 150)}`);
}
const counter = edges.find((e) => e.relation === "contradicts" && e.to_id === "CLM-001");
console.log(counter ? `3 ok: real counter-evidence ${counter.from_id} contradicts CLM-001` : "3 NOTE: no contradicts edge this run");
console.log("stats after run:", await stats());

// 5. audit timeline
await page.click('[data-view="timeline"]');
await page.waitForSelector("#trail .entry");
const trail = await page.$eval("#trail", (e) => e.innerText);
for (const phrase of ["imported", "answered", "asked the agent to challenge", "approve"]) assert.ok(trail.includes(phrase), `timeline mentions "${phrase}"`);
await page.screenshot({ path: `${SHOTS}/timeline_all.png` });
await page.select("#trailActor", "PM:");
const pmOnly = await page.$$eval("#trail .actor", (els) => els.map((e) => e.textContent));
assert.ok(pmOnly.length > 0 && pmOnly.every((a) => a.startsWith("PM:")), "PM filter shows only PM entries");
await page.select("#trailActor", "");
await page.select("#jump", "CLM-001");
await page.click("#trailChain");
const chainIds = await page.$$eval("#trail .entry", (els) => els.map((e) => e.dataset.id));
assert.ok(chainIds.includes("CLM-001") && chainIds.includes("DEC-001") && !chainIds.includes("SRC-001") === false, "chain filter keeps the claim's chain");
await page.screenshot({ path: `${SHOTS}/timeline_chain.png` });
console.log("5 ok: timeline phrases, PM filter, chain filter:", chainIds.join(" "));

// 6. clicking a timeline entry selects the node; switching back to the graph keeps it
await page.click('#trail [data-id="QST-002"]');
await page.waitForFunction(() => document.querySelector("#detail h2").textContent.includes("QST-002"));
await page.click('[data-view="graph"]');
await page.waitForFunction(() => window.cy.getElementById("QST-002").selected());
console.log("6 ok: entry click selects, graph keeps selection");
assert.deepEqual(errors, [], "no page errors");
await browser.close();
console.log("all phase 4 checks passed");
